-- Idempotent baseline generated from the inspected D1 schema. Safe for existing tables.

CREATE TABLE IF NOT EXISTS admin_sessions (     id TEXT PRIMARY KEY,     admin_id TEXT NOT NULL,     token_hash TEXT NOT NULL UNIQUE,     expires_at TEXT NOT NULL,     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     FOREIGN KEY (admin_id)         REFERENCES admins(id) ON DELETE CASCADE );

CREATE TABLE IF NOT EXISTS admins (     id TEXT PRIMARY KEY,     email TEXT NOT NULL UNIQUE COLLATE NOCASE,     password_hash TEXT NOT NULL,     display_name TEXT NOT NULL,     is_active INTEGER NOT NULL DEFAULT 1         CHECK (is_active IN (0, 1)),     last_login_at TEXT,     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );

CREATE TABLE IF NOT EXISTS categories (     id TEXT PRIMARY KEY,     name TEXT NOT NULL,     slug TEXT NOT NULL UNIQUE COLLATE NOCASE,     description TEXT,     image_key TEXT,     sort_order INTEGER NOT NULL DEFAULT 0,     is_active INTEGER NOT NULL DEFAULT 1         CHECK (is_active IN (0, 1)),     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );

CREATE TABLE IF NOT EXISTS collections (     id TEXT PRIMARY KEY,     name TEXT NOT NULL,     slug TEXT NOT NULL UNIQUE COLLATE NOCASE,     description TEXT,     cover_image_key TEXT,     launch_date TEXT,     status TEXT NOT NULL DEFAULT 'draft'         CHECK (status IN ('draft', 'published', 'archived')),     sort_order INTEGER NOT NULL DEFAULT 0,     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );

CREATE TABLE IF NOT EXISTS menu_groups (     id TEXT PRIMARY KEY,     name TEXT NOT NULL,     slug TEXT NOT NULL UNIQUE COLLATE NOCASE,     sort_order INTEGER NOT NULL DEFAULT 0,     is_active INTEGER NOT NULL DEFAULT 1         CHECK (is_active IN (0, 1)),     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );

CREATE TABLE IF NOT EXISTS menu_items (     id TEXT PRIMARY KEY,     group_id TEXT NOT NULL,     label TEXT NOT NULL,     slug TEXT NOT NULL,     target_type TEXT NOT NULL         CHECK (             target_type IN (                 'all_products',                 'category',                 'collection',                 'page',                 'url'             )         ),     target_id TEXT,     external_url TEXT,     sort_order INTEGER NOT NULL DEFAULT 0,     is_active INTEGER NOT NULL DEFAULT 1         CHECK (is_active IN (0, 1)),     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),      FOREIGN KEY (group_id)         REFERENCES menu_groups(id) ON DELETE CASCADE,      UNIQUE (group_id, slug),      CHECK (         (target_type = 'url'             AND external_url IS NOT NULL             AND target_id IS NULL)         OR         (target_type <> 'url'             AND target_id IS NOT NULL             AND external_url IS NULL)     ) );

CREATE TABLE IF NOT EXISTS pages (     id TEXT PRIMARY KEY,     title TEXT NOT NULL,     slug TEXT NOT NULL UNIQUE COLLATE NOCASE,     content TEXT,     status TEXT NOT NULL DEFAULT 'draft'         CHECK (status IN ('draft', 'published')),     meta_title TEXT,     meta_description TEXT,     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );

CREATE TABLE IF NOT EXISTS product_images (     id TEXT PRIMARY KEY,     product_id TEXT NOT NULL,     image_key TEXT NOT NULL,     alt_text TEXT,     sort_order INTEGER NOT NULL DEFAULT 0,     is_primary INTEGER NOT NULL DEFAULT 0         CHECK (is_primary IN (0, 1)),     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),      FOREIGN KEY (product_id)         REFERENCES products(id) ON DELETE CASCADE );

CREATE TABLE IF NOT EXISTS product_sizes (     id TEXT PRIMARY KEY,     product_id TEXT NOT NULL,     size TEXT NOT NULL,     sku TEXT UNIQUE,     stock INTEGER NOT NULL DEFAULT 0         CHECK (stock >= 0),     is_available INTEGER NOT NULL DEFAULT 1         CHECK (is_available IN (0, 1)),     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),      FOREIGN KEY (product_id)         REFERENCES products(id) ON DELETE CASCADE,      UNIQUE (product_id, size) );

CREATE TABLE IF NOT EXISTS products (     id TEXT PRIMARY KEY,     category_id TEXT NOT NULL,     collection_id TEXT,     name TEXT NOT NULL,     slug TEXT NOT NULL UNIQUE COLLATE NOCASE,     description TEXT,     price_cop INTEGER NOT NULL CHECK (price_cop >= 0),     compare_price_cop INTEGER         CHECK (compare_price_cop IS NULL OR compare_price_cop >= 0),     status TEXT NOT NULL DEFAULT 'draft'         CHECK (status IN ('draft', 'published', 'archived')),     is_featured INTEGER NOT NULL DEFAULT 0         CHECK (is_featured IN (0, 1)),     sort_order INTEGER NOT NULL DEFAULT 0,     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),      FOREIGN KEY (category_id)         REFERENCES categories(id) ON DELETE RESTRICT,      FOREIGN KEY (collection_id)         REFERENCES collections(id) ON DELETE SET NULL );

CREATE TABLE IF NOT EXISTS social_links (     id TEXT PRIMARY KEY,     platform TEXT NOT NULL,     label TEXT NOT NULL,     url TEXT NOT NULL,     sort_order INTEGER NOT NULL DEFAULT 0,     is_active INTEGER NOT NULL DEFAULT 1         CHECK (is_active IN (0, 1)),     created_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );

CREATE TABLE IF NOT EXISTS store_settings (     setting_key TEXT PRIMARY KEY,     setting_value TEXT,     updated_at TEXT NOT NULL DEFAULT         (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );
